FAMILIES.rm.modes=RM_MODELS.map(m=>({name:'Dwa odcinki. Jeden sygnał.',type:`${m.label} · ${m.pins} ${m.pins<5?'TORY':'TORÓW'}`,ports:[],rm:m}));
function rmStrip(x,y,m){
 const padY=c=>y+3+c*26/(m.pins-1);
 let leds='';
 for(let i=0;i<6;i++){
  const lx=x+17+i*23;
  if(m.key==='mono')leds+=`<rect class="acc-led-shell" x="${lx}" y="${y+6}" width="13" height="20" rx="1"/><rect class="acc-rm-mono" x="${lx+3}" y="${y+9}" width="7" height="14" rx="1"/>`;
  else if(m.key==='cct')leds+=`<rect class="acc-led-shell" x="${lx}" y="${y+5}" width="13" height="22" rx="1"/><rect class="acc-cct-warm" x="${lx+3}" y="${y+7}" width="7" height="8" rx="1"/><rect class="acc-cct-cool" x="${lx+3}" y="${y+17}" width="7" height="8" rx="1"/>`;
  else{leds+=`<rect class="acc-led-shell" x="${lx}" y="${y+9}" width="13" height="14" rx="1"/><rect class="acc-rm-rgb" x="${lx+2}" y="${y+11}" width="9" height="10" rx="2"/>`;
   if(m.key==='rgbw')leds+=`<rect class="acc-led-shell" x="${lx+15}" y="${y+11}" width="6" height="10" rx="1"/><rect class="acc-rm-white" x="${lx+16}" y="${y+12}" width="4" height="8"/>`;
   if(m.key==='rgbcct')leds+=`<rect class="acc-cct-warm" x="${lx+15}" y="${y+6}" width="5" height="8" rx="1"/><rect class="acc-cct-cool" x="${lx+15}" y="${y+18}" width="5" height="8" rx="1"/>`;
  }
 }
 return `<g data-rm-strip="${m.key}"><rect class="multi-pcb" x="${x}" y="${y}" width="158" height="32" rx="1"/>${m.labels.map((label,c)=>`<path class="multi-track" d="M${x+5} ${padY(c)}h148"/><rect class="multi-pad" x="${x}" y="${padY(c)-1.5}" width="7" height="3"/><rect class="multi-pad" x="${x+151}" y="${padY(c)-1.5}" width="7" height="3"/>`).join('')}${leds}</g>`;
}
function rmDrawing(m){
 const ox=198,oy=58,scale=2.3,inputs=m.inputs.map(x=>ox+x*scale),outputs=Array.from({length:18},(_,i)=>ox+(6.95+i*4.333)*scale);
 let levers='';
 for(let i=0;i<18;i++){
  const active=i>=m.spareSlots,color=active?m.colors[(i-m.spareSlots)%m.pins]:'#a8b2ab';
  levers+=`<rect data-rm-output="${active?'active':'spare'}" x="${(5.15+i*4.333).toFixed(3)}" y="53" width="3.6" height="9.7" rx=".5" fill="${color}"/>`;
 }
 for(let c=0;c<m.pins;c++)levers+=`<rect data-rm-input x="${m.inputs[c]-2.75}" y="3.2" width="5.5" height="13.6" rx=".7" fill="${m.colors[c]}"/>`;
 const wires=[];
 for(let c=0;c<m.pins;c++){
  const color=m.colors[c],py=281+c*26/(m.pins-1),first=m.spareSlots+c,last=18-m.pins+c;
  wires.push(`<path class="acc-rm-wire" data-rm-wire="input" style="stroke:${color}" pathLength="1" d="M${inputs[c]} 21V66"/>`);
  wires.push(`<path class="acc-rm-wire" data-rm-wire="output" style="stroke:${color}" pathLength="1" d="M${outputs[first]} 207V${230+c*6}H${36-c*5}V${py}H42"/>`);
  wires.push(`<path class="acc-rm-wire" data-rm-wire="output" style="stroke:${color}" pathLength="1" d="M${outputs[last]} 207V${230+(m.pins-1-c)*6}H${564+c*5}V${py}H558"/>`);
 }
 return `<path class="multi-dimension" d="M300 18V296M35 160H565"/><text class="acc-diagram-text" x="300" y="13" text-anchor="middle">SYGNAŁ ${m.label}</text>${wires.join('')}
 <g transform="translate(${ox} ${oy}) scale(${scale})"><path class="acc-rm-body" d="M0 21.69C0 9.71 9.71 0 21.67 0H66.29C78.26 0 87.98 9.71 87.98 21.69V64.5Q87.98 67.65 84.9 67.65H3.1Q0 67.65 0 64.5Z"/>${levers}<path class="acc-rm-original" d="${m.path}"/></g>
 <text class="acc-rm-title" x="298" y="144" text-anchor="middle">PRESCOT</text><text class="acc-rm-sub" x="298" y="160" text-anchor="middle">${m.sku} · 1 → ${m.branches}</text><text class="acc-diagram-text" x="${outputs[m.spareSlots]}" y="225">01</text><text class="acc-diagram-text" x="${outputs[18-m.pins]}" y="225">${String(m.branches).padStart(2,'0')}</text>${rmStrip(42,278,m)}${rmStrip(400,278,m)}${inputs.map((x,c)=>`<text class="acc-terminal" x="${x}" y="54">${m.labels[c]}</text>`).join('')}`;
}

function pcbDrawing(mode){
  if(mode==='TT')return `<rect class="acc-classic-shell" x="-46" y="-31" width="92" height="62" rx="6"/><path class="multi-contact" d="M-42 -15H42v8H-42ZM-42 7H42v8H-42Z"/><g class="acc-classic-lid"><rect class="acc-classic-shell" x="-38" y="-28" width="76" height="56" rx="4"/><path class="multi-outline" d="M-31 -21H31v42H-31Z"/></g>`;
  const ports=mode==='L'?[180,90]:mode==='T'?[180,0,90]:[180,0,90,270];
  const arms=ports.map(a=>`<g transform="rotate(${a})"><rect class="acc-pcb-board" x="-21" y="-23" width="78" height="46"/><rect class="multi-pad" x="31" y="-16" width="19" height="10" rx="4"/><rect class="multi-pad" x="31" y="6" width="19" height="10" rx="4"/><text class="multi-polarity" x="18" y="-7">+</text><text class="multi-polarity" x="18" y="14">−</text><g class="acc-solder"><ellipse class="acc-solder-tin" cx="54" cy="-12" rx="10" ry="5"/><ellipse class="acc-solder-tin" cx="54" cy="12" rx="10" ry="5"/><path class="acc-solder-glint" d="M48 -14q5-4 10 0M48 10q5-4 10 0"/></g></g>`).join('');
  return `<g>${arms}<rect class="acc-pcb-board" x="-23" y="-23" width="46" height="46"/><text class="acc-pcb-type" x="0" y="5" text-anchor="middle">${mode}</text></g>`;
}

export function initConnectorCard(card){
  const stage=card.querySelector('[data-multi-technical]'),drawing=card.querySelector('[data-multi-drawing]');
  if(!stage||!drawing)return {start(){},stop(){}};
  const qs=s=>card.querySelector(s);
  const modeName=qs('[data-multi-name]'),type=qs('[data-multi-type]'),status=qs('[data-multi-status]'),modes=qs('[data-multi-modes]');
  const familyButtons=[...card.querySelectorAll('[data-acc-family]')];
  let family='multi',current=-1,markers=[],branches=[],frame=0,started=0,running=false,reduced=false,manual=null,lastPaint=0,lastSelection=-1000,renderedFrames=0,imageToken=0,rmIndex=1;
  const cycle=5400;
  function render(index){
    const mode=FAMILIES[family].modes[index];current=index;card.dataset.multiMode=String(index+1);
    modeName.textContent=mode.name;type.textContent=mode.type;
    markers.forEach((m,i)=>{m.classList.toggle('is-current',i===index);m.setAttribute('aria-pressed',String(i===index));});
    if(family==='lock')drawing.innerHTML=lockDrawing();
    else if(family==='rm'){drawing.innerHTML=rmDrawing(mode.rm);syncRM(mode.rm);}
    else{
      const ports=mode.ports.map(([kind,angle,stripType])=>{
        const mirror=angle===180||(kind==='strip'&&angle===90)||(kind==='wire'&&angle===270);
        return `<g class="multi-branch" data-angle="${angle}" data-kind="${kind}" data-strip-type="${stripType||mode.type}"><g transform="scale(1 ${mirror?-1:1})">${kind==='wire'?wire(angle%180!==0):strip(stripType||mode.type,angle%180!==0,family==='pcb')}</g></g>`;
      }).join('');
      drawing.innerHTML=`<path class="multi-dimension" d="M35 155H565M300 18V298"/><path class="multi-outline" d="M31 151v8m538-8v8M296 20h8m-8 275h8"/><g transform="translate(300 155)">${ports}${family==='pcb'?pcbDrawing(mode.pcb):connector(mode.rotated)}</g>`;
    }
    branches=[...drawing.querySelectorAll('.multi-branch')];
  }
  function modeForCurrent(){return FAMILIES[family].modes[Math.max(0,current)];}
  function pose(t,complete=false,lightTime=t){
    branches.forEach((branch,i)=>{
      const angle=Number(branch.dataset.angle),distance=branch.dataset.kind==='strip'?68:40;
      const seat=family==='pcb'&&modeForCurrent().pcb!=='TT'?54:0;
      const gap=seat+(complete?0:distance*(1-ease((t-350-i*120)/1300)));
      branch.setAttribute('transform',`translate(${(Math.cos(angle*Math.PI/180)*gap).toFixed(2)} ${(Math.sin(angle*Math.PI/180)*gap).toFixed(2)}) rotate(${angle})`);
    });
    const connected=complete||t>2050,seated=complete||t>(family==='lock'?2650:2450),powered=complete||t>(family==='lock'?3000:2850);
    const turn=complete?1:ease((t-1800)/850);
    stage.style.setProperty('--acc-turn',turn.toFixed(4));stage.style.setProperty('--acc-solder',String(complete?1:ease((t-1850)/650)));
    const orbit=drawing.querySelector('.acc-lock-orbit');if(orbit){const a=(-.24+turn*.5)*Math.PI;orbit.setAttribute('transform',`translate(0 ${(155+Math.sin(a)*22).toFixed(2)}) scale(1 ${Math.cos(a).toFixed(4)})`);drawing.querySelector('[data-lock-step]').textContent=powered?'NIEZAWODNE POŁĄCZENIE':connected?'OBRÓT WOKÓŁ OSI':'WSUNIĘCIE';}
    stage.style.setProperty('--acc-gap',String(complete?0:1-ease((t-300)/1600)));
    stage.style.setProperty('--acc-connect',String(complete?1:ease((t-350)/1900)));
    stage.style.setProperty('--acc-warm',String(powered?(complete?.65:.5+.45*Math.sin((t-2900)/1100)):.12));
    stage.style.setProperty('--acc-cool',String(powered?(complete?.35:.5-.45*Math.sin((t-2900)/1100)):.12));
    if(family==='rm'){
      const m=RM_MODELS[rmIndex],time=Math.max(0,lightTime-2900)/1000;
      const warm=reduced?.65:.5+.45*Math.sin(time*.7),white=reduced?.6:.4+.35*Math.sin(time*.43);
      stage.style.setProperty('--acc-warm',String(powered?warm:.12));stage.style.setProperty('--acc-cool',String(powered?1-warm:.12));
      stage.style.setProperty('--acc-rm-mono',String(powered?(reduced?.85:.78+.2*Math.sin(time*.55)):.1));
      stage.style.setProperty('--acc-rm-white',String(powered?white:.08));
      const hue=reduced?205:(time*18+205)%360;stage.style.setProperty('--acc-rm-rgb',powered?`hsl(${hue.toFixed(1)} 88% 65%)`:'#668575');
      stage.style.setProperty('--acc-rm-color-level',String(powered?(m.key==='rgb'?1:1-white*.5):.15));
    }
    stage.classList.toggle('multi-seated',seated);stage.classList.toggle('multi-powered',powered);
    stage.dataset.phase=powered?(family==='lock'?'locked':'lit'):seated?'locked':connected?(family==='lock'?'turning':family==='pcb'?'soldering':'contact'):'joining';
    status.textContent=powered?(family==='lock'?'ZABLOKOWANO':'POŁĄCZONO'):seated?'STYK':connected?'DOMKNIĘCIE':'ŁĄCZENIE';
    drawing.style.opacity=String(complete?1:Math.min(1,ease(t/300),ease((cycle-t)/400)));
  }
  function tick(now){
    frame=0;if(!running||reduced||document.hidden)return;
    if(now-lastPaint<1000/30-1){frame=requestAnimationFrame(tick);return;}lastPaint=now;
    const elapsed=Math.max(0,now-started),index=family==='rm'?rmIndex:manual??(Math.floor(elapsed/cycle)%FAMILIES[family].modes.length);
    if(index!==current)render(index);
    const completed=family!=='rm'&&(manual!==null||family==='lock')&&elapsed>=3500;
    if(family==='rm')pose(Math.min(3500,elapsed),elapsed>=3500,elapsed);
    else pose(manual===null&&family!=='lock'?elapsed%cycle:Math.min(3500,elapsed),completed);renderedFrames++;
    if(!completed)frame=requestAnimationFrame(tick);
  }
  function restart(){cancelAnimationFrame(frame);frame=0;started=performance.now()-120;lastPaint=0;pose(120,reduced);renderedFrames++;if(running&&!reduced&&!document.hidden)frame=requestAnimationFrame(tick);}
  function select(index){
    index=Number(index);if(!Number.isInteger(index)||!FAMILIES[family].modes[index])return;
    const now=performance.now();if(manual===index&&now-lastSelection<200)return;
    lastSelection=now;manual=index;if(family==='rm')rmIndex=index;render(index);restart();
  }
  function bindButtons(buttons,onSelect){
    buttons.forEach((button,i)=>{
      button.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch')onSelect(i);});
      button.addEventListener('focus',()=>onSelect(i));button.addEventListener('click',()=>onSelect(i));
      button.addEventListener('keydown',e=>{const n=buttons.length;const next=e.key==='ArrowRight'?(i+1)%n:e.key==='ArrowLeft'?(i+n-1)%n:e.key==='Home'?0:e.key==='End'?n-1:null;if(next!==null){e.preventDefault();buttons[next].focus();}});
    });
  }
  function loadFamilyPhoto(){
    const f=family==='rm'?{image:RM_MODELS[rmIndex].photo,alt:`Oryginalny rozdzielacz PRESCOT ${RM_MODELS[rmIndex].sku} — ${RM_MODELS[rmIndex].branches} wyjść`}:FAMILIES[family],night=document.documentElement.dataset.theme!=='day';
    const websitePair=family==='lock'&&night&&!!card.closest('.offer-page,.home-page');
    const src=websitePair?'/prescotled/noir/media/connector-lock-white-open-pair.svg':family==='lock'&&night?'/prescotled/noir/media/connector-lock-white-original.png':f.image;
    const alt=websitePair?'Oryginalne białe gniazdo i wtyk PRESCOT DC LOCK przed połączeniem':family==='lock'?(night?'Oryginalne białe złącza PRESCOT DC LOCK — gniazdo, wtyk i połączona para':'Oryginalne czarne gniazdo i wtyk PRESCOT DC LOCK'):f.alt;
    const token=++imageToken,photo=qs('[data-acc-photo]');
    if(photo.getAttribute('src')!==src){photo.style.opacity='0';const next=new Image();next.src=src;next.decode().then(()=>{if(token!==imageToken)return;photo.src=src;photo.alt=alt;photo.style.opacity='1';}).catch(()=>{if(token===imageToken)photo.style.opacity='0';});}else photo.style.opacity='1';
  }
  addEventListener('prescot:themechange',()=>{if(family==='lock')loadFamilyPhoto()});
  function syncRM(m){
    card.dataset.rmModel=m.key;loadFamilyPhoto();
    qs('[data-acc-eyebrow]').textContent=`${m.sku} · 1 → ${m.branches}`;
    qs('[data-acc-copy]').textContent=m.copy;
    qs('[data-acc-diagram-label]').textContent=`${m.sku} / PODŁĄCZENIE`;
    qs('[data-acc-note]').textContent=`Pokazano 2 z ${m.branches} wyjść. 5–48 V DC · 25 A łącznie / 10 A na gałąź. Wspólny sygnał sterownika.`;
  }
  function selectFamily(key,initial=false){
    if(!FAMILIES[key]||(!initial&&key===family))return;
    family=key;card.dataset.accFamily=key;manual=null;current=-1;
    const f=FAMILIES[key];
    qs('[data-acc-eyebrow]').textContent=f.eyebrow;qs('[data-acc-title]').textContent=f.title;qs('[data-acc-copy]').textContent=f.copy;
    qs('[data-acc-diagram-label]').textContent=f.label;qs('[data-acc-note]').textContent=f.note;
    const link=qs('[data-acc-link]');link.href=f.href;link.innerHTML=`Poznaj ${f.name} <span aria-hidden="true">↗</span>`;
    loadFamilyPhoto();
    familyButtons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.accFamily===key)));
    modes.classList.toggle('acc-rm-models',key==='rm');modes.setAttribute('aria-label',key==='rm'?'Wybierz model rozdzielacza RM':'Wybierz układ połączenia');
    modes.innerHTML=key==='rm'?RM_MODELS.map((m,i)=>`<button type="button" class="multi-mode acc-rm-model" data-rm-model="${m.key}" aria-label="${m.sku}, ${m.label}, jedno wejście i ${m.branches} wyjść" aria-pressed="false"><strong>${m.label}</strong><small>1 → ${m.branches}</small></button>`).join(''):f.modes.length>1?f.modes.map((m,i)=>`<button type="button" class="multi-mode" aria-label="${i+1}. ${m.name} — ${m.type}" aria-pressed="false"><span>${String(i+1).padStart(2,'0')}</span>${icon(m)}</button>`).join(''):'';
    markers=[...modes.children];bindButtons(markers,select);modes.dataset.count=String(markers.length);
    render(key==='rm'?rmIndex:0);restart();
  }
  bindButtons(familyButtons,i=>selectFamily(familyButtons[i].dataset.accFamily));
  selectFamily('multi',true);pose(0,true);card.classList.add('multi-ready');
  return {
    start(options={}){if(running)return;running=true;reduced=!!options.reduced;render(Math.max(0,current));restart();},
    stop(){running=false;cancelAnimationFrame(frame);frame=0;},
    select,selectFamily,
    inspect:()=>({family,mode:current+1,manual:manual===null?null:manual+1,phase:stage.dataset.phase,running,playing:!!frame,reduced,renderedFrames,source:qs('[data-acc-photo]').getAttribute('src'),axialTurn:Number(stage.style.getPropertyValue('--acc-turn')),solder:Number(stage.style.getPropertyValue('--acc-solder')),rmModel:family==='rm'?RM_MODELS[rmIndex].key:null,sku:family==='rm'?RM_MODELS[rmIndex].sku:null,inputPins:family==='rm'?RM_MODELS[rmIndex].pins:null,outputPins:family==='rm'?RM_MODELS[rmIndex].outputPins:null,outputBranches:family==='rm'?RM_MODELS[rmIndex].branches:null,spareSlots:family==='rm'?RM_MODELS[rmIndex].spareSlots:null})
  };
}
